import AgentPreset from '@deepseek-ai/dsh-agent-preset';
import {dshHomePath} from '@deepseek-ai/dsh-home-paths';
import * as dataHost from './packages/natural-data/index.js';
import {configureAnswerQualityDirectory} from './packages/natural-data/answer-guard.js';
import {join} from 'node:path';
import {startEngine} from './runtime.js';

export const name = 'natural-ask-data';
export const inject = ['webServer', 'connection', 'sessionController', 'workspaceRegistry', 'agentPresets'];

export async function apply(ctx, config = {}) {
  const dataRoot = config.dataRoot || dshHomePath('plugin-data', 'ask-data');
  const lifetime = new AbortController();
  let engine;
  ctx.effect(() => async () => {
    lifetime.abort();
    dataHost.configureTransport({endpoint: null, token: null});
    await engine?.stop();
  });
  engine = await startEngine({dataRoot, python: config.python, signal: lifetime.signal});
  if (lifetime.signal.aborted) {await engine.stop(); return;}
  dataHost.configureTransport(engine);
  configureAnswerQualityDirectory(join(dataRoot, 'answer-quality'));
  dataHost.apply(ctx);
  ctx.plugin(AgentPreset, {
    id: 'natural-data', name: '智能问数', order: 2,
    description: '查询和分析已授权的项目数据，在当前回答中展示图表及执行依据。',
    plugins: [
      {id: 'persona', name: '@deepseek-ai/dsh-persona', config: {prefix: '你是问数助手。通过受控数据工具完成查询与分析。'}},
      {id: 'natural-capabilities', name: '@natural-work/ask-data/capabilities', config: {capabilities: ['data', 'analysis', 'work', 'knowledge']}},
      {id: 'tool-ask-user', name: '@deepseek-ai/dsh-tool-ask-user'},
      {id: 'compaction', name: 'cordis:group', group: true, isolate: {compaction: true}, config: [{id: 'compaction-basic', name: '@deepseek-ai/dsh-compaction-basic'}, {id: 'command-compact', name: '@deepseek-ai/dsh-command-compact'}]}
    ]
  });
}
